#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
helper="$root/.github/scripts/ci-compiled-server.sh"
installer="$root/.github/scripts/ci-install-hurl.sh"
wf="$root/.github/workflows/ci.yml"
BASH_RUN="${BASH:-bash}"; pass=0; fail=0
record() { if [ "$2" -eq "$3" ]; then echo "PASS $1 (rc=$2)"; pass=$((pass+1)); else echo "FAIL $1 (rc=$2 want=$3)"; fail=$((fail+1)); fi; }
expect_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "PASS $1"; pass=$((pass+1)); else echo "FAIL $1"; fail=$((fail+1)); fi; }
reject_txt() { if printf '%s\n' "$2" | grep -F -- "$3" >/dev/null; then echo "FAIL $1"; fail=$((fail+1)); else echo "PASS $1"; pass=$((pass+1)); fi; }
scratch=$(mktemp -d); trap 'rm -rf "$scratch"' EXIT; mkdir -p "$scratch/bin" "$scratch/rt" "$scratch/static" "$scratch/install"
write_bin() { printf '%s\n' "$2" > "$scratch/bin/$1"; chmod +x "$scratch/bin/$1"; }
term_node() { printf '%s\n' '#!/bin/sh' 'echo $$ > "$RUNNER_TEMP/node.pid"' "trap \"exit $1\" TERM" 'while true; do sleep 0.05; done' > "$scratch/bin/node"; chmod +x "$scratch/bin/node"; }
ok_make() { write_bin make $'#!/bin/sh\n[ "$1" = "$EXPECT_TARGET" ] || exit 9\necho fake make ok; exit 0'; }
alive_pid() { [ -f "$1" ] && kill -0 "$(cat "$1")" 2>/dev/null; }
pid_of() { [ -f "$1" ] && cat "$1" || true; }
assert_dead() { if alive_pid "$1"; then echo "FAIL $2"; fail=$((fail+1)); kill -KILL "$(cat "$1")" 2>/dev/null || true; else echo "PASS $2"; pass=$((pass+1)); fi; }
reap_pids() { for p in "$@"; do [ -n "${p:-}" ] && kill -KILL "$p" 2>/dev/null || true; k=0; while [ -n "${p:-}" ] && [ "$k" -lt 40 ] && kill -0 "$p" 2>/dev/null; do sleep 0.05; k=$((k+1)); done; done; }
ck_sent() { if kill -0 "$1" 2>/dev/null; then echo "PASS $2"; pass=$((pass+1)); kill -TERM "$1" 2>/dev/null || true; wait "$1" 2>/dev/null || true; else echo "FAIL $2"; fail=$((fail+1)); fi; }
with_h() { PATH="$scratch/bin:/usr/bin:/bin" RUNNER_TEMP="$scratch/rt" HOST=127.0.0.1 PORT=18016 SMOKE_BASE_URL=http://127.0.0.1:18016 UI_WALK_BASE_URL=http://127.0.0.1:18016 DB_PATH="$scratch/rt/app.db" STATIC_ROOT="$scratch/static" EXPECT_TARGET="${EXPECT_TARGET:-smoke}" CI_TERM_WAIT="${CI_TERM_WAIT:-2}" CI_KILL_WAIT="${CI_KILL_WAIT:-1}" CI_READY_SLEEP="${CI_READY_SLEEP:-0.05}" "$@"; }
run_helper() { EXPECT_TARGET="$1" with_h "$BASH_RUN" "${2:-$helper}" "$1"; }
waitf() { n=0; while [ "$n" -lt 80 ] && [ ! -f "$1" ]; do sleep 0.05; n=$((n+1)); done; [ -f "$1" ] || { echo "FAIL missing ${1##*/}"; fail=$((fail+1)); }; }
waitp() { n=0; while [ "$n" -lt 80 ] && kill -0 "$1" 2>/dev/null; do sleep 0.05; n=$((n+1)); done; }
bg() { with_h exec "$BASH_RUN" "$1" smoke >"$2" 2>&1 & wp=$!; }
ed() { python3 -c 'import sys;s=open(sys.argv[1]).read();p,n=sys.argv[3],sys.argv[4];sys.exit(2) if s.count(p)!=1 else open(sys.argv[5],"w").write(s.replace(p,n,1) if sys.argv[2]=="r" else s[:s.find(p)+len(p)]+"\n"+n+"\n"+s[s.find(p)+len(p):])' "$1" "$2" "$3" "$4" "$5" && chmod +x "$5"; }
inj() { ed "${4:-$helper}" i "$2" "$3" "$1" || { echo "FAIL inj $2"; fail=$((fail+1)); printf '%s\n' '#!/bin/sh' 'exit 2' > "$1"; chmod +x "$1"; }; }
mark() { inj "$1" 'ec=$?' ': > "$RUNNER_TEMP/cleanup.mark"'; }
bar() { inj "$1" 'on_exit() {' ': > "$RUNNER_TEMP/cleanup.mark"; while [ ! -f "$RUNNER_TEMP/cleanup.go" ]; do sleep 0.05; done' "${2-}"; }
start_bg() { sleep 30 & sentinel=$!; rm -f "$scratch/rt/"*.pid "$scratch/rt/"*.mark "$scratch/rt/"*.go; set +e; bg "$1" "$2"; }
check_wf() { python3 -c 'exec('"'"'import sys\ntry:\n import re\n import sys\n \n text = open(sys.argv[1], "rb").read().decode().split("\\n")\n if text and text[-1] == "":\n     text.pop()\n key = r"(?:[A-Za-z_][A-Za-z0-9_-]*|\'"'"'[A-Za-z_][A-Za-z0-9_-]*\'"'"'|\\"[A-Za-z_][A-Za-z0-9_-]*\\")"\n pair_re = re.compile(r"^( *)(" + key + r"):(?: (.*))?$")\n \n \n def active(line):\n     return bool(line.strip()) and not line.lstrip().startswith("#")\n \n \n def width(line):\n     return len(line) - len(line.lstrip(" "))\n \n \n def pair(line, expected_width):\n     match = pair_re.match(line)\n     if not match or len(match.group(1)) != expected_width:\n         raise ValueError\n     name = match.group(2)\n     return (name[1:-1] if name[0] in "\'"'"'\\"" else name), match.group(3)\n \n \n def fail_if_tab(line):\n     if "\\t" in line:\n         raise ValueError\n \n \n top = {}\n jobs_at = None\n for number, line in enumerate(text):\n     if not active(line) or line.startswith(" "):\n         continue\n     fail_if_tab(line)\n     name, value = pair(line, 0)\n     if name in top:\n         raise ValueError\n     top[name] = value\n     if name == "jobs":\n         jobs_at = number\n if jobs_at is None or top["jobs"] is not None or "env" in top or "defaults" in top:\n     raise ValueError\n \n headers = []\n header_names = set()\n end = len(text)\n for number in range(jobs_at + 1, len(text)):\n     line = text[number]\n     if not active(line):\n         continue\n     if width(line) == 0:\n         end = number\n         break\n     if width(line) == 2:\n         fail_if_tab(line)\n         name, value = pair(line, 2)\n         if value is not None or name in header_names:\n             raise ValueError\n         header_names.add(name)\n         headers.append((name, number))\n ranges = {\n     name: (number + 1, headers[index + 1][1] if index + 1 < len(headers) else end)\n     for index, (name, number) in enumerate(headers)\n }\n if any(name not in ranges for name in ("smoke", "ui-walk", "all-checks-passed")):\n     raise ValueError\n \n \n def parse_job(start, stop):\n     metadata = []\n     metadata_names = set()\n     steps = []\n     current = None\n     env_open = False\n     body = None\n     body_open = False\n     in_steps = False\n     for line in text[start:stop]:\n         fail_if_tab(line)\n         if body_open:\n             if width(line) >= 10:\n                 body.append(line)\n                 continue\n             body_open = False\n         if not active(line):\n             continue\n         level = width(line)\n         if not in_steps:\n             if level != 4:\n                 raise ValueError\n             name, value = pair(line, 4)\n             if name in metadata_names:\n                 raise ValueError\n             metadata_names.add(name)\n             metadata.append((name, value))\n             if name == "steps":\n                 if value is not None:\n                     raise ValueError\n                 in_steps = True\n             continue\n         if level == 6:\n             if not line.startswith("      - "):\n                 raise ValueError\n             name, value = pair(line[8:], 0)\n             current = {"properties": [(name, value)], "names": {name}, "env": None, "env_names": set()}\n             steps.append(current)\n             env_open = False\n             continue\n         if level == 8:\n             if current is None:\n                 raise ValueError\n             name, value = pair(line, 8)\n             if name in current["names"]:\n                 raise ValueError\n             current["names"].add(name)\n             current["properties"].append((name, value))\n             env_open = name == "env" and value is None\n             if env_open:\n                 current["env"] = []\n             if name == "run" and value == "|":\n                 body = []\n                 body_open = True\n             continue\n         if level == 10 and current is not None and env_open:\n             name, value = pair(line, 10)\n             if name in current["env_names"]:\n                 raise ValueError\n             current["env_names"].add(name)\n             current["env"].append((name, value))\n             continue\n         raise ValueError\n     if not in_steps:\n         raise ValueError\n     return (\n         tuple(metadata),\n         tuple((tuple(step["properties"]), None if step["env"] is None else tuple(step["env"])) for step in steps),\n         None if body is None else tuple(body),\n     )\n \n setup = (("uses", "actions/setup-node@v4"), ("with", "{ node-version-file: .tool-versions, cache: npm }"))\n common = (\n     ((("uses", "actions/checkout@v4"),), None),\n     (setup, None),\n     ((("run", "npm ci"),), None),\n     ((("run", "npm run build --workspace web"),), None),\n     ((("run", "npm run build --workspace server"),), None),\n )\n smoke_env = (\n     ("HOST", \'"'"'"127.0.0.1"\'"'"'),\n     ("PORT", \'"'"'"18016"\'"'"'),\n     ("SMOKE_BASE_URL", \'"'"'"http://127.0.0.1:18016"\'"'"'),\n     ("DB_PATH", \'"'"'"${{ runner.temp }}/workbuddy-smoke/app.db"\'"'"'),\n     ("STATIC_ROOT", \'"'"'"${{ github.workspace }}/smoke/fixtures/static"\'"'"'),\n )\n ui_env = (\n     ("HOST", \'"'"'"127.0.0.1"\'"'"'),\n     ("PORT", \'"'"'"18017"\'"'"'),\n     ("UI_WALK_BASE_URL", \'"'"'"http://127.0.0.1:18017"\'"'"'),\n     ("DB_PATH", \'"'"'"${{ runner.temp }}/workbuddy-ui-walk/app.db"\'"'"'),\n     ("STATIC_ROOT", \'"'"'"${{ github.workspace }}/web/dist"\'"'"'),\n )\n smoke = (\n     (("runs-on", "ubuntu-latest"), ("timeout-minutes", "10"), ("steps", None)),\n     common + (\n         ((("name", "install hurl 8.0.1"), ("run", "bash .github/scripts/ci-install-hurl.sh")), None),\n         ((("name", "smoke compiled server"), ("env", None), ("run", "bash .github/scripts/ci-compiled-server.sh smoke")), smoke_env),\n     ),\n     None,\n )\n ui = (\n     (("runs-on", "ubuntu-latest"), ("timeout-minutes", "15"), ("steps", None)),\n     common + (\n         ((("run", "npx playwright install --with-deps chromium"),), None),\n         ((("name", "ui-walk compiled server"), ("env", None), ("run", "bash .github/scripts/ci-compiled-server.sh ui-walk")), ui_env),\n     ),\n     None,\n )\n body = (\n     "          results=" + chr(39) + "${{ toJSON(needs) }}" + chr(39),\n     "          echo \\"$results\\"",\n     "          if echo \\"$results\\" | grep -Eq " + chr(39) + "\\"result\\": *\\"(failure|cancelled|skipped)\\"" + chr(39) + "; then",\n     "            echo \\"some required job did not succeed (failure/cancelled/skipped)\\"; exit 1",\n     "          fi",\n )\n aggregate = (\n     (("if", "always()"), ("needs", "[fast-checks, unit-tests, anti-drift, secret-scan, sast, smoke, ui-walk]"), ("runs-on", "ubuntu-latest"), ("steps", None)),\n     (((("name", "verify all required jobs succeeded"), ("run", "|")), None),),\n     body,\n )\n \n if parse_job(*ranges["smoke"]) != smoke:\n     raise ValueError\n if parse_job(*ranges["ui-walk"]) != ui:\n     raise ValueError\n if parse_job(*ranges["all-checks-passed"]) != aggregate:\n     raise ValueError\nexcept Exception:\n sys.exit(1)\n'"'"')' "$1"; }
if check_wf "$wf" && ! grep -F -q 'harness.out' "$helper" && ! grep -F -q 'pipe.rc' "$helper"; then echo "PASS workflow invokes exact helpers"; pass=$((pass+1)); else echo "FAIL workflow helper wiring"; fail=$((fail+1)); fi
wf_mut() { python3 -c 'import sys;s=open(sys.argv[1]).read();old,new=sys.argv[3],sys.argv[4];sys.exit(2) if s.count(old)!=1 else open(sys.argv[2],"w").write(s.replace(old,new,1))' "$wf" "$scratch/wf.yml" "$1" "$2"; }
expect_wf() { if wf_mut "$3" "$4"; then if check_wf "$scratch/wf.yml"; then rc=0; else rc=$?; fi; record "$1" "$rc" "$2"; else echo "FAIL $1 missing anchor"; fail=$((fail+1)); fi; }
reject_mut() { expect_wf "$1" 1 "$2" "$3"; }; accept_mut() { expect_wf "$1" 0 "$2" "$3"; }; muts() { while [ "$#" -ge 3 ]; do reject_mut "$1" "$2" "$3"; shift 3; done; }
