ks-passed:\n' $'  all-checks-passed:\n    continue-on-error: true\n' "smoke job if" $'  smoke:\n    runs-on: ubuntu-latest\n' $'  smoke:\n    if: false\n    runs-on: ubuntu-latest\n' "ui job if" $'  ui-walk:\n    runs-on: ubuntu-latest\n' $'  ui-walk:\n    if: false\n    runs-on: ubuntu-latest\n'
